package com.medtrack.user.entity;
import com.medtrack.auth.entity.Role; import com.medtrack.shared.model.BaseEntity; import com.medtrack.warehouse.entity.Warehouse; import jakarta.persistence.*;
@Entity @Table(name="users") public class User extends BaseEntity { @Column(nullable=false,unique=true) private String email; @Column(name="password_hash",nullable=false) private String passwordHash; @Column(name="full_name",nullable=false) private String fullName; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="role_id",nullable=false) private Role role; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="assigned_warehouse_id") private Warehouse assignedWarehouse; @Enumerated(EnumType.STRING) @Column(nullable=false) private UserStatus status; protected User(){} public String getEmail(){return email;} public String getPasswordHash(){return passwordHash;} public String getFullName(){return fullName;} public Role getRole(){return role;} public Warehouse getAssignedWarehouse(){return assignedWarehouse;} public UserStatus getStatus(){return status;} }
